draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-130);
  ctx.lineTo(W/2, H/2-80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2-30, H/2-50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2+30, H/2-50);
  ctx.stroke();

  // wisdom bubbles
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2-70, H/2-200, 20+10*Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2-70, H/2-200, 20+10*Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1091', W/2-70, H/2-200);

  ctx.beginPath();
  ctx.arc(W/2+70, H/2-200, 20+10*Math.cos(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2+70, H/2-200, 20+10*Math.cos(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('LESSON', W/2+70, H/2-200);

  ctx.restore();
}
